import{_ as a}from"./chunks/prontera-church.uydloSKv.js";import{c as l,Q as i,j as r,m as e}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"新手入坑完全指南","description":"RO3 从零开始注册、下载、建角色到快速上手","frontmatter":{"title":"新手入坑完全指南","description":"RO3 从零开始注册、下载、建角色到快速上手","lastUpdated":true},"headers":[],"relativePath":"guide/newbie.md","filePath":"guide/newbie.md","lastUpdated":1780229775000}'),o={name:"guide/newbie.md"};function d(n,t,h,s,u,c){return i(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="新手入坑完全指南" tabindex="-1">新手入坑完全指南 <a class="header-anchor" href="#新手入坑完全指南" aria-label="Permalink to &quot;新手入坑完全指南&quot;">​</a></h1><h2 id="游戏基础信息" tabindex="-1">游戏基础信息 <a class="header-anchor" href="#游戏基础信息" aria-label="Permalink to &quot;游戏基础信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>游戏名称</td><td>RO3 仙境传说3（Ragnarok Online 3）</td></tr><tr><td>开发商</td><td>Gravity × JoyMaker</td></tr><tr><td>类型</td><td>MMORPG（跨平台 PC / iOS / Android）</td></tr><tr><td>发行时间</td><td>2026年（全球同步上线）</td></tr><tr><td>收费模式</td><td>免费游玩 + 内购</td></tr><tr><td>语言</td><td>简中 / 繁中 / 英文 / 日文等多语言</td></tr></tbody></table><p><img src="'+a+'" alt="RO3 游戏画面预览"></p><h2 id="设备要求" tabindex="-1">设备要求 <a class="header-anchor" href="#设备要求" aria-label="Permalink to &quot;设备要求&quot;">​</a></h2><h3 id="pc-最低配置" tabindex="-1">PC 最低配置 <a class="header-anchor" href="#pc-最低配置" aria-label="Permalink to &quot;PC 最低配置&quot;">​</a></h3><ul><li>系统：Windows 10 64-bit</li><li>CPU：Intel i5 或同等</li><li>内存：8GB</li><li>显卡：GTX 960 或同等</li></ul><h3 id="手机最低配置" tabindex="-1">手机最低配置 <a class="header-anchor" href="#手机最低配置" aria-label="Permalink to &quot;手机最低配置&quot;">​</a></h3><ul><li>iOS：iPhone 11 或更新机种</li><li>Android：骁龙 845 / 麒麟 980 或同等，6GB 内存</li></ul><h2 id="开局流程" tabindex="-1">开局流程 <a class="header-anchor" href="#开局流程" aria-label="Permalink to &quot;开局流程&quot;">​</a></h2><h3 id="第一步-下载游戏" tabindex="-1">第一步：下载游戏 <a class="header-anchor" href="#第一步-下载游戏" aria-label="Permalink to &quot;第一步：下载游戏&quot;">​</a></h3><ol><li>官网 <a href="https://ro3global.com" target="_blank" rel="noreferrer">https://ro3global.com</a> 注册账号</li><li>选择 PC 下载或手机应用商店下载</li><li>安装完成后启动器更新</li></ol><h3 id="第二步-创建角色" tabindex="-1">第二步：创建角色 <a class="header-anchor" href="#第二步-创建角色" aria-label="Permalink to &quot;第二步：创建角色&quot;">​</a></h3><ol><li>选择服务器（建议选最新服，人多且经济活跃）</li><li>选择职业（参考 <a href="/guide/job-pick.html">职业选择推荐</a>）</li><li>自定义外观（发型、脸型、肤色等）</li></ol><h3 id="第三步-新手任务-1-30级" tabindex="-1">第三步：新手任务（1-30级） <a class="header-anchor" href="#第三步-新手任务-1-30级" aria-label="Permalink to &quot;第三步：新手任务（1-30级）&quot;">​</a></h3><ol><li>跟随主线任务指引，熟悉基本操作</li><li>学会使用技能、吃药、装备更换</li><li>10级时学习第一个主动技能</li><li>20级可接取转职任务</li><li>建议新手先练到 25 级再转职</li></ol><h3 id="第四步-日常活动-30级后" tabindex="-1">第四步：日常活动（30级后） <a class="header-anchor" href="#第四步-日常活动-30级后" aria-label="Permalink to &quot;第四步：日常活动（30级后）&quot;">​</a></h3><ul><li><strong>每日副本</strong>：经验副本 3 次</li><li><strong>公会任务</strong>：贡献度任务</li><li><strong>限时活动</strong>：世界 BOSS / 护送</li><li><strong>挂机练级</strong>：找对应等级地图挂机</li></ul><h2 id="必知要点" tabindex="-1">必知要点 <a class="header-anchor" href="#必知要点" aria-label="Permalink to &quot;必知要点&quot;">​</a></h2><h3 id="_1-赛季制" tabindex="-1">1. 赛季制 <a class="header-anchor" href="#_1-赛季制" aria-label="Permalink to &quot;1. 赛季制&quot;">​</a></h3><p>RO3 采用赛季制（每赛季 3-4 个月），赛季结束后：</p><ul><li>角色数据保留</li><li>重新开启新赛季内容</li><li>赛季奖励仅当赛季可获取</li></ul><h3 id="_2-自动战斗" tabindex="-1">2. 自动战斗 <a class="header-anchor" href="#_2-自动战斗" aria-label="Permalink to &quot;2. 自动战斗&quot;">​</a></h3><ul><li>自动战斗效率约为手动的 70%-80%</li><li>日常练级可以挂机解决</li><li>BOSS 战 / GVG 需要手动操作</li></ul><h3 id="_3-经济系统" tabindex="-1">3. 经济系统 <a class="header-anchor" href="#_3-经济系统" aria-label="Permalink to &quot;3. 经济系统&quot;">​</a></h3><ul><li><strong>Zeny</strong>：基础货币，怪物掉落/任务获得</li><li><strong>绑定 Zeny</strong>：绑定的货币，用于绑定交易</li><li><strong>信用评分</strong>：交易信用体系，影响摆摊权限</li></ul><h3 id="_4-装备成长" tabindex="-1">4. 装备成长 <a class="header-anchor" href="#_4-装备成长" aria-label="Permalink to &quot;4. 装备成长&quot;">​</a></h3><ul><li>打怪掉落 → 装备制作 → 精炼强化 → 卡片镶嵌</li><li>详见 <a href="/guide/crafting.html">装备制作与精炼指南</a></li></ul><h2 id="省钱攻略" tabindex="-1">省钱攻略 <a class="header-anchor" href="#省钱攻略" aria-label="Permalink to &quot;省钱攻略&quot;">​</a></h2><ul><li><strong>零氪推荐职业</strong>：剑士、牧师</li><li><strong>微氪推荐职业</strong>：法师、刺客</li><li><strong>不推荐的消费</strong>：开服直接抽卡（等赛季中期价格稳定再入手）</li><li><strong>必买项目</strong>：月卡（如果有）、仓库扩展</li></ul><h2 id="每日必做清单" tabindex="-1">每日必做清单 <a class="header-anchor" href="#每日必做清单" aria-label="Permalink to &quot;每日必做清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级区间</th><th>必做任务</th></tr></thead><tbody><tr><td>1-30 级</td><td>主线任务、转职任务</td></tr><tr><td>30-60 级</td><td>每日副本 ×3、公会任务、挂机练级</td></tr><tr><td>60-99 级</td><td>高级副本、世界 BOSS、GVG、摆摊交易</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>不要急着转职</strong>：20 级就转职会导致技能点不够，前期打怪吃力，建议 25+ 级再转</li><li><strong>不要乱点技能</strong>：技能点有限，建议按攻略加点，否则后期洗点需要花钱</li><li><strong>不要忽视生活技能</strong>：采集、制作、钓鱼等生活技能是稳定的收入来源</li><li><strong>不要单刷高难本</strong>：RO3 强调组队协作，组队效率远高于单刷</li><li><strong>不要囤积低级材料</strong>：低级材料价格会快速贬值，及时出手换 Zeny</li></ol>',34)])])}const q=l(o,[["render",d]]);export{m as __pageData,q as default};
